// One event record drives entry routes, completed stages, summaries, and lists.
state.taskFilter='전체';
const eventFields=['eventName','brandId','basic','selectedTemplate','creationCustom','gameDraft','layers','pageLayers','studioPage','settings','consent','approved','paid','published','paused','ended','retried','reportPublished','aiReport','confirmedReport','reportText','metricVisibility'];
function eventKey(brand,name){return brand+'|'+name}
function captureEvent(){state.pageLayers[state.studioPage]=state.layers;const record={};for(const key of eventFields)record[key]=state[key];return JSON.parse(JSON.stringify(record))}
function restoreEvent(record){Object.assign(state,JSON.parse(JSON.stringify(record)));state.layerHistory=[];state.layerId=state.layers.some(l=>l.id==='title')?'title':state.layers[0]?.id||'';state.gameDraftMode=false;state.editorTab='디자인';state.aiLayerDraft='';state.toolTab='레이어'}
function deriveEventFlow(record){const design=!!((record.selectedTemplate&&record.settings?.designSaved&&record.consent)||record.approved||record.published),review=!!record.approved,publish=!!record.published,operate=!!record.ended,report=!!record.settings?.reportShared;const entry=operate?'report':publish?'operate':review?'publish':design&&record.settings?.reviewRequested?'review':'editor';return {entry,done:{editor:design,review,publish,operate,report},status:operate?'종료':publish?'진행 중':review?'시작 예정':design&&record.settings?.reviewRequested?'검토 중':'작성 중'}}
const seedRestore=captureEvent();
for(const e of eventData){const b=brands.find(b=>b.short===e[1]);state.eventName=e[0];state.brandId=b.id;state.basic={name:e[0],start:e[4].startsWith('09')?'2026-09-21':'2026-10-'+(b.id==='novahome'?'20':b.id==='greenday'?'24':'12'),end:e[4].startsWith('09')?'2026-09-23':'2026-10-'+(b.id==='novahome'?'22':b.id==='greenday'?'25':'16'),type:b.id==='novahome'?'박람회·전시':'팝업스토어',place:b.id==='lumiere'?'성수 팝업 안내 데스크':'',channel:'오프라인'};state.selectedTemplate=/스크래치/.test(e[0])?'nova-scratch':/퀴즈/.test(e[0])?'green-quiz':'lumiere-wheel';state.creationCustom=true;state.gameDraft=null;state.settings={designSaved:true,reviewRequested:e[2]==='검토 중',consentText:state.organizationConsent};state.consent=true;state.approved=['시작 예정','진행 중','종료'].includes(e[2]);state.paid=['진행 중','종료'].includes(e[2]);state.published=['진행 중','종료'].includes(e[2]);state.ended=e[2]==='종료';state.paused=false;state.retried=false;state.reportPublished=false;state.aiReport=false;state.confirmedReport=false;state.reportText='';resetLayers();rewards();if(state.approved)state.settings.reviewApproval={signature:approvalSignature(),status:'확정',time:'저장된 확정 시안'};state.eventMemory[eventKey(b.id,e[0])]=captureEvent()}
Object.assign(state,seedRestore);
retainEvent=function(){if(state.eventName&&!state.gameDraftMode)state.eventMemory[eventKey(state.brandId,state.eventName)]=captureEvent()};
function allEventRows(){return eventData.map(e=>{const b=brands.find(x=>x.short===e[1]),record=state.eventMemory[eventKey(b.id,e[0])];return {e,brand:b,record,flow:deriveEventFlow(record)}})}
function taskCounts(row){const settings=row.record.settings;return {failed:row.record.retried?0:Number(settings.failedCount??(row.e[0]==='루미에르 성수 팝업 룰렛'?5:0)),comments:Number(settings.openComments??(row.flow.status==='검토 중'?2:0)),ready:row.flow.done.review&&!row.flow.done.publish?1:0}}
function taskTotals(){return allEventRows().filter(r=>r.flow.status!=='종료').reduce((sum,r)=>{const t=taskCounts(r);for(const k of ['failed','comments','ready'])sum[k]+=t[k];return sum},{failed:0,comments:0,ready:0})}
function taskText(row){const t=taskCounts(row),labels=[];if(t.failed)labels.push('발송 실패 '+t.failed+'건');if(t.comments)labels.push('시안 의견 '+t.comments+'건');if(t.ready)labels.push('게시 준비');return labels.length?labels.map(t=>`<span class="event-task-count">${t}</span>`).join(''):'<span class="dim">—</span>'}
openWorkspaceEvent=function(n){retainEvent();const key=eventKey(n.dataset.eventBrand,n.dataset.openEvent),record=state.eventMemory[key];if(!record)return toast('행사 정보를 찾을 수 없습니다.');restoreEvent(record);state.wsTab='행사';const target=deriveEventFlow(record).entry;go(target)};
stageCompletion=function(){return deriveEventFlow(captureEvent()).done};
function selectTaskFilter(kind){state.taskFilter=state.taskFilter===kind?'전체':kind;state.filter='전체';state.brandFilter='전체';state.eventChannelFilters.home='전체';render()}
eventTable=function(){let rows=allEventRows().filter(r=>eventChannelMatches(r.record.basic)).filter(r=>(state.filter==='전체'||r.flow.status===state.filter)&&(state.brandFilter==='전체'||r.brand.id===state.brandFilter));if(route()==='home')rows=rows.filter(r=>r.flow.status!=='종료');if(route()==='home'&&state.taskFilter!=='전체')rows=rows.filter(r=>taskCounts(r)[state.taskFilter]>0);return `<div class="table-wrap"><table class="event-table task-event-table"><thead><tr><th>행사</th><th>운영 방식</th><th>상태</th><th>확인할 작업</th><th>기간</th></tr></thead><tbody>${rows.length?rows.map(r=>`<tr class="clickable event-navigation-row" tabindex="0" data-open-event="${esc(r.e[0])}" data-event-brand="${r.brand.id}" data-event-status="${r.flow.status}" aria-label="${esc(r.e[0])} 행사 열기"><td><div class="event-cell"><div class="event-icon">${r.brand.initial}</div><div><div class="event-name">${esc(r.e[0])}</div>${badge(r.brand.short)}</div></div></td><td class="event-channel">${eventChannel(r.record.basic)}</td><td>${pill(r.flow.status,r.flow.status==='검토 중'?'review':r.flow.status==='시작 예정'?'scheduled':r.flow.status==='종료'?'ended':'')}</td><td class="event-tasks">${taskText(r)}</td><td class="dim">${esc(r.e[4])}</td></tr>`).join(''):'<tr><td colspan="5" class="empty-events">조건에 맞는 행사가 없습니다.</td></tr>'}</tbody></table></div>`};
const taskHome=home;home=function(){let h=taskHome(),totals=taskTotals();h=h.replace(/<div class="desk-tasks">[\s\S]*?<\/div><section class="desk-events">/,`<div class="desk-tasks">${[['failed','발송 실패 확인',totals.failed,'건'],['comments','시안 의견',totals.comments,'건'],['ready','게시 준비',totals.ready,'개 행사']].map(([kind,label,count,unit])=>`<button data-task-filter="${kind}" class="${state.taskFilter===kind?'selected':''}" aria-pressed="${state.taskFilter===kind}"><strong>${label}</strong><b>${count}<small>${unit}</small></b></button>`).join('')}</div><section class="desk-events">`);if(state.taskFilter!=='전체')h=h.replace('<div class="filters">',`<div class="task-filter-note"><button class="text-link" data-task-filter="전체">전체 보기</button></div><div class="filters">`);return h};
const noPromptCopy=templates;templates=function(){return noPromptCopy().replace('<span class="mini-label">초안은 만든 뒤 수정할 수 있어요.</span>','')};
notificationTasks=function(){return allEventRows().filter(r=>r.flow.status!=='종료').flatMap(r=>{const t=taskCounts(r);return [['failed','발송 실패 확인',t.failed],['comments','시안 의견 확인',t.comments],['ready','게시 준비',t.ready]].filter(v=>v[2]>0).map(([kind,label,count])=>({kind,label,count,detail:r.e[0],status:r.flow.status,brandId:r.brand.id,name:r.e[0]}))})};
notificationToolbar=function(){const tasks=notificationTasks();return `<div class="top-actions task-notifications"><button class="notification-button" data-action="task-notifications" aria-label="확인할 작업" aria-expanded="${state.notificationsOpen}" aria-controls="task-popover">${lineIcon('bell')}${tasks.length?'<i class="notification-dot"></i>':''}</button>${state.notificationsOpen?`<section id="task-popover" class="task-popover" aria-label="확인할 작업"><div class="panel-head"><h2>확인할 작업</h2><button data-action="task-notifications" aria-label="닫기">${uiIcon('close')}</button></div>${tasks.map(t=>`<button class="notification-task" data-notification-event="${esc(t.name)}" data-notification-brand="${t.brandId}"><span><strong>${t.label}</strong><small>${esc(t.detail)}</small></span><b>${t.count}</b></button>`).join('')||'<p class="mini-label">확인할 작업이 없습니다.</p>'}</section>`:''}</div>`};
function navigateEventStep(target){const flow=deriveEventFlow(captureEvent());if(target==='publish'&&!flow.done.review){navigateEventStep('review');toast('게임 확정 후 게시를 준비할 수 있습니다.');return}if(['operate','report'].includes(target)&&!flow.done.publish){go(flow.entry);toast('게시한 뒤 이용할 수 있습니다.');return}if(target==='review'&&!flow.done.editor){state.editorTab=state.consent?'디자인':'수집·동의';go('editor');toast('제작 설정을 완료한 뒤 검토해주세요.');return}if(target==='review')state.settings.reviewRequested=true;retainEvent();go(target)}
const flowStateAction=action;action=function(a,n){if(a==='to-review'){navigateEventStep('review');return}if(a==='to-publish'){navigateEventStep('publish');return}flowStateAction(a,n);if(['save','approve','pay','pause','end','retry','confirm-report','share-report'].includes(a)){retainEvent();render()}};
// Existing brands have example uploaded wordmarks. New ones start without media/color.
for(const b of brands){const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="480" height="160" viewBox="0 0 480 160"><rect width="480" height="160" rx="16" fill="${b.soft}"/><text x="240" y="92" text-anchor="middle" fill="${b.color}" font-family="sans-serif" font-size="32" font-weight="600">${b.name}</text></svg>`;b.logoImage='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);b.logoFilename=b.id+'-logo.svg';b.colorAssigned=true}
function brandAssets(){const b=currentBrand();return `<section class="panel brand-assets"><div class="field"><label>브랜드 이미지</label>${b.logoImage?`<div class="brand-uploaded"><img src="${b.logoImage}" alt="${esc(b.name)} 브랜드 이미지"><span class="mini-label">${esc(b.logoFilename||'브랜드 이미지')}</span><div class="inline"><label class="btn secondary" for="brand-image-upload">이미지 변경</label><button class="text-link" data-brand-asset="remove">삭제</button></div></div>`:`<label class="brand-upload-empty" for="brand-image-upload">${uiIcon('templates')}<strong>브랜드 이미지 업로드</strong><span>PNG · JPG · SVG</span></label>`}<input type="file" id="brand-image-upload" accept="image/png,image/jpeg,image/webp,image/svg+xml" hidden></div><div class="field"><label for="brand-wordmark">이미지가 없을 때 표시할 이름</label><input id="brand-wordmark" value="${esc(b.wordmark||b.name)}"></div><div class="field"><label for="workspace-color">대표 색상</label><div class="brand-color-editor"><input type="color" id="workspace-color" value="${b.colorAssigned?b.color:'#222222'}"><span>${b.colorAssigned?esc(b.color):'미지정'}</span></div>${!b.colorAssigned?'<p class="mini-label">색상을 선택하면 게임에 적용할 수 있습니다.</p>':''}</div><button class="btn secondary" data-brand-asset="save">저장</button></section>`}
const assetBrandDetail=brandDetail;brandDetail=function(){let h=assetBrandDetail();if(state.wsTab==='브랜드 자료')h=h.replace(/<section class="panel brand-assets">[\s\S]*?<\/section>/,brandAssets());return h};
const newWorkspaceAction=action;action=function(a,n){const before=brands.length;newWorkspaceAction(a,n);if(a==='brand-confirm'&&brands.length>before){const b=currentBrand();b.logoImage=null;b.logoFilename='';b.colorAssigned=false;b.color='#222222';b.soft='#f3f3f1';state.wsTab='브랜드 자료';render()}};
const flowBrandBind=bind;bind=function(){flowBrandBind();app.querySelectorAll('[data-task-filter]').forEach(n=>n.onclick=()=>selectTaskFilter(n.dataset.taskFilter));app.querySelectorAll('[data-event-step]').forEach(n=>n.onclick=()=>navigateEventStep(n.dataset.eventStep));app.querySelectorAll('[data-notification-event]').forEach(n=>n.onclick=()=>{state.notificationsOpen=false;openWorkspaceEvent({dataset:{eventBrand:n.dataset.notificationBrand,openEvent:n.dataset.notificationEvent}})});app.querySelectorAll('[data-brand-asset]').forEach(n=>n.onclick=()=>{const b=currentBrand();if(n.dataset.brandAsset==='remove'){b.logoImage=null;b.logoFilename='';render();return}b.wordmark=document.getElementById('brand-wordmark').value.trim()||b.name;toast('브랜드 자료를 저장했습니다.')});const color=document.getElementById('workspace-color');if(color)color.oninput=()=>{const b=currentBrand();b.color=color.value;b.colorAssigned=true;const label=app.querySelector('.brand-color-editor span');if(label)label.textContent=color.value};const image=document.getElementById('brand-image-upload');if(image)image.onchange=()=>{const file=image.files?.[0];if(!file)return;if(file.size>5*1024*1024)return toast('5MB 이하 이미지를 선택해주세요.');if(!/^image\/(png|jpeg|webp|svg\+xml)$/.test(file.type))return toast('이미지 파일을 선택해주세요.');const reader=new FileReader();reader.onload=()=>{const b=currentBrand();b.logoImage=reader.result;b.logoFilename=file.name;render();toast('브랜드 이미지를 첨부했습니다.')};reader.readAsDataURL(file)}};
render();
const captureRecord=retainEvent;retainEvent=function(){captureRecord();if(!state.eventName||state.gameDraftMode)return;const record=state.eventMemory[eventKey(state.brandId,state.eventName)],flow=deriveEventFlow(record),b=currentBrand(),period=state.basic.start&&state.basic.end?state.basic.start.slice(5).replace('-','.')+' — '+state.basic.end.slice(5).replace('-','.'):'';let e=eventData.find(v=>v[0]===state.eventName&&v[1]===b.short);if(!e){e=[state.eventName,b.short,flow.status,flow.entry,period,flow.entry,''];eventData.push(e)}e[2]=flow.status;e[3]=({editor:'제작',review:'검토',publish:'게시',operate:'운영',report:'성과'})[flow.entry];e[5]=flow.entry;if(period)e[4]=period;const row=b.list.find(v=>v[0]===state.eventName);if(row)row[1]=flow.status;else b.list.push([state.eventName,flow.status,'0건']);b.events=b.list.length;b.active=b.list.filter(v=>v[1]!=='종료').length};
openWorkspaceEvent=function(n){retainEvent();const key=eventKey(n.dataset.eventBrand,n.dataset.openEvent),record=state.eventMemory[key];if(!record)return toast('행사 정보를 찾을 수 없습니다.');restoreEvent(record);if(state.approved&&!approvalCurrent())invalidateApproval();retainEvent();state.wsTab='행사';go(deriveEventFlow(captureEvent()).entry)};
const assetSaveAction=action;action=function(a,n){assetSaveAction(a,n);if(a==='resolve'){state.settings.openComments=Math.max(0,(state.settings.openComments??2)-1);retainEvent()}};
render();
